wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(361235053850457615)
,p_process_sequence=>80
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(361234223255457606)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Organization Category Sets - Save Interactive Grid Data'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_sequence NUMBER;',
'    l_org_id   NUMBER;',
'    l_active   VARCHAR2(1);',
'    l_required VARCHAR2(1);',
'    l_old_seq  NUMBER;',
'BEGIN',
'    -- Adhesives Research | Joel Calzadilla | 2026-10-14',
'    -- Page 90: Organization Category Sets.',
'    -- Assign positions per organization; detect concurrent changes.',
'    -- Serialize configuration saves before calculating MAX + 10.',
'    LOCK TABLE ops.adre_inv_item_org_cat_set',
'        IN SHARE ROW EXCLUSIVE MODE NOWAIT;',
'',
'    IF :APEX$ROW_STATUS = ''C'' THEN',
'        SELECT NVL(MAX(orcase.display_sequence), 0) + 10',
'          INTO l_sequence',
'          FROM ops.adre_inv_item_org_cat_set orcase',
'         WHERE orcase.ebs_organization_id = :EBS_ORGANIZATION_ID;',
'',
'        INSERT INTO ops.adre_inv_item_org_cat_set',
'        (',
'            ebs_organization_id, ebs_category_set_id,',
'            active_flag, required_flag, display_sequence',
'        )',
'        VALUES',
'        (',
'            :EBS_ORGANIZATION_ID, :EBS_CATEGORY_SET_ID,',
'            NVL(:ACTIVE_FLAG, ''Y''), NVL(:REQUIRED_FLAG, ''N''),',
'            l_sequence',
'        )',
'        RETURNING ROWID, display_sequence, active_flag, required_flag',
'             INTO :ROW_KEY, :DISPLAY_SEQUENCE,',
'                  :ORIGINAL_ACTIVE_FLAG, :ORIGINAL_REQUIRED_FLAG;',
'',
'        :ORIGINAL_DISPLAY_SEQUENCE := l_sequence;',
'',
'    ELSIF :APEX$ROW_STATUS IN (''U'', ''D'') THEN',
'        SELECT orcase.ebs_organization_id,',
'               orcase.active_flag,',
'               orcase.required_flag,',
'               orcase.display_sequence',
'          INTO l_org_id, l_active, l_required, l_old_seq',
'          FROM ops.adre_inv_item_org_cat_set orcase',
'         WHERE orcase.ROWID = CHARTOROWID(:ROW_KEY);',
'',
'        IF :ORIGINAL_ACTIVE_FLAG IS NULL',
'           OR :ORIGINAL_REQUIRED_FLAG IS NULL',
'           OR :ORIGINAL_DISPLAY_SEQUENCE IS NULL',
'           OR l_active <> :ORIGINAL_ACTIVE_FLAG',
'           OR l_required <> :ORIGINAL_REQUIRED_FLAG',
'           OR l_old_seq <> :ORIGINAL_DISPLAY_SEQUENCE',
'        THEN',
'            RAISE_APPLICATION_ERROR(-20001,',
'                ''This row has changed. Refresh the report and try again.'');',
'        END IF;',
'',
'        IF :APEX$ROW_STATUS = ''U'' THEN',
'            l_sequence := l_old_seq;',
'',
'            -- Moving to another organization assigns its next position.',
'            IF l_org_id <> :EBS_ORGANIZATION_ID THEN',
'                SELECT NVL(MAX(orcase.display_sequence), 0) + 10',
'                  INTO l_sequence',
'                  FROM ops.adre_inv_item_org_cat_set orcase',
'                 WHERE orcase.ebs_organization_id =',
'                       :EBS_ORGANIZATION_ID;',
'            END IF;',
'',
'            UPDATE ops.adre_inv_item_org_cat_set',
'               SET ebs_organization_id = :EBS_ORGANIZATION_ID,',
'                   ebs_category_set_id = :EBS_CATEGORY_SET_ID,',
'                   active_flag = :ACTIVE_FLAG,',
'                   required_flag = :REQUIRED_FLAG,',
'                   display_sequence = l_sequence',
'             WHERE ROWID = CHARTOROWID(:ROW_KEY);',
'',
'            :DISPLAY_SEQUENCE := l_sequence;',
'            :ORIGINAL_ACTIVE_FLAG := :ACTIVE_FLAG;',
'            :ORIGINAL_REQUIRED_FLAG := :REQUIRED_FLAG;',
'            :ORIGINAL_DISPLAY_SEQUENCE := l_sequence;',
'        ELSE',
'            DELETE FROM ops.adre_inv_item_org_cat_set',
'             WHERE ROWID = CHARTOROWID(:ROW_KEY);',
'        END IF;',
'    END IF;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RAISE_APPLICATION_ERROR(-20002,',
'            ''This row no longer exists. Refresh the report.'');',
'    WHEN DUP_VAL_ON_INDEX THEN',
'        RAISE_APPLICATION_ERROR(-20003,',
'            ''This Category Set is already configured for this organization.'');',
'    WHEN OTHERS THEN',
'        IF SQLCODE = -54 THEN',
'            RAISE_APPLICATION_ERROR(-20004,',
'                ''Configuration is being updated. Please try saving again.'');',
'        ELSE',
'            RAISE;',
'        END IF;',
'END;'))
,p_attribute_05=>'N'
,p_attribute_06=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>340786709155356342
);
end;
/
